    _get_ptx_module().function("conv_transpose3d_kernel")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super().__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels,
            out_channels,
            kernel_size=(kernel_size, kernel_size, kernel_size),
            stride=stride,
            padding=padding,
            output_padding=output_padding,
            groups=groups,
            bias=bias,
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        conv = self.conv_transpose3d
        batch_size = int(x.shape[0])
        in_channels = int(x.shape[1])
        in_depth = int(x.shape[2])
        in_height = int(x.shape[3])
        in_width = int(x.shape[4])

        out_channels = int(conv.out_channels)
        kernel_depth, kernel_height, kernel_width = (int(v) for v in conv.kernel_size)
        stride_depth, stride_height, stride_width = (int(v) for v in conv.stride)
        pad_depth, pad_height, pad_width = (int(v) for v in conv.padding)
        output_pad_depth, output_pad_height, output_pad_width = (int(v) for v in conv.output_padding)
        groups = int(conv.groups)

        out_depth = (in_depth - 1) * stride_depth - 2 * pad_depth + kernel_depth + output_pad_depth
        out_height = (in_height - 1) * stride_height - 2 * pad_height + kernel_height + output_pad_height
        out_width = (in_width - 1) * stride_width - 2 * pad_width + kernel_width + output_pad_width

        output = torch.empty(
            (batch_size, out_channels, out_depth, out_height, out_width),
            device=x.device,
            dtype=x.dtype,
        )

        weight = conv.weight
        bias = conv.bias
        bias_argument = bias if bias is not None else output
        has_bias = 1 if bias is not None else 0

        total_elements = batch_size * out_channels * out_depth * out_height * out_width
        specialized = (
            in_channels == 48
            and out_channels == 48
            and groups == 1
            and (kernel_depth, kernel_height, kernel_width) == (3, 3, 3)
            and (stride_depth, stride_height, stride_width) == (1, 1, 1)
        )
        work_items = total_elements // out_channels if specialized else total_elements
        blocks = (work_items + 255) // 256

        _get_ptx_module().launch(
            "conv_transpose3d_kernel",
            grid=(blocks, 1, 1),
            block=(256, 1, 1),
            arguments=[
                x,
                weight,
                bias_argument,
                output,
                u64(batch_size),
                u64(in_channels),
                u64(out_channels),
                u64(in_depth),
                u64(in_height),
                u64(in_width),
                u64(out_depth),
                u64(out_height),
                u64(out_width),
                u64(kernel_depth),
                u64(kernel_height),
                u64(kernel_width),
                u64(stride_depth),
                u64(stride_height),
                u64(stride_width),
                u64(pad_depth),
                u64(pad_height),
                u64(pad_width),
                u64(groups),
                u64(total_elements),
                u32(has_bias),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return output
